    ancient_lore: 'Ancient Egyptians mined malachite in the Sinai for over 4,000 years. Ground malachite was used as green eye shadow (kohl) and as a pigment for paintings. It was sacred to Hathor, goddess of love and beauty. The Romans called it "Molochitis" and carved it into amulets for children to ward off evil. Russian Tsars used it extensively for architectural decoration — the Malachite Room in the Winter Palace is legendary.',
    indigenous_traditions: 'Various African traditions use malachite as a protective amulet and a stone of power. In some Congolese shamanic lineages it is considered a spirit-mirror and used for divination.',

    meditation_guidance: 'Malachite is a powerful tool for shadow work and deep emotional processing. Hold it or place it on the Heart chakra and allow whatever arises to arise — do not suppress it. This is not a stone for beginners to use alone in deep work; it amplifies everything. Best used with conscious intention and the support of an experienced guide for deep transformational sessions. After working with malachite, always cleanse it promptly and cleanse yourself.',
    body_placement: 'Heart chakra for emotional transformation; Solar Plexus for personal power work. Use for short periods rather than extended wear — its transformative intensity can be overwhelming. Remove if you feel dizzy, nauseous, or emotionally overwhelmed.',
    space_placement: 'Spaces of intentional transformation — therapy rooms, healing spaces, altars for change work. Avoid placing in relaxation spaces. Its energy is active and demanding, not passive and restful.',
    elixir_safety: 'Avoid',
    elixir_notes: 'SAFETY WARNING: Malachite contains copper carbonate hydroxide. Copper leaches into water and is toxic in significant quantities. Raw malachite dust is particularly dangerous if inhaled. Never use malachite in direct crystal elixirs under any circumstances. This applies to polished specimens as well. If a malachite elixir is absolutely required, use triple-indirect methods and consult a qualified crystal healer.',
    jewelry_recommendations: 'Stunning in polished cabochons, carvings, and pendants. Mohs 4 — too soft for rings worn daily; better in pendants and earrings. Always use polished, sealed specimens in jewelry. Handle with dry hands — perspiration and skin acids can gradually damage the surface. Do not shower or swim while wearing malachite jewelry.',

    safe_cleansing: ['Dry smudging (smoke)', 'Sound bath', 'Visualization and breath — preferred method', 'Moonlight (dry surface)'],
    unsafe_cleansing: ['Water in any form (copper will leach; stone can be damaged)', 'Salt or salt water (severely damaging)', 'Sunlight (can fade color)'],
    charging_methods: ['Moonlight (no moisture)', 'Visualization of green transformative fire', 'Placed on a copper plate or near copper objects'],
    storage_guidance: 'Store dry. Do not store in humid environments — copper oxidizes. Keep away from water. Wrap in dry cloth. Keep raw specimens separately from polished ones. Wash hands thoroughly after handling raw malachite — the dust is a real health concern.',
    cautions: 'HEALTH WARNING: Raw malachite dust is toxic if inhaled — never sand, cut, or grind malachite without proper respiratory protection. Wash hands after all handling. Do not use for elixirs. Keep away from children and pets when raw. Polished, sealed specimens are much safer but still require hand-washing after use.',
    toxicity: 'Copper carbonate — toxic if ingested or inhaled as dust; polished specimens are safer but require hand-washing',
    fragility: 'High — Mohs 4, very soft; easily scratched; water and acid sensitive',

    synergies: [
      { crystal: 'Black Tourmaline', id: 'black-tourmaline', rationale: 'Malachite brings deep patterns to the surface; black tourmaline grounds and seals the aura after the work is done. Essential pairing for safe deep transformation work — malachite stirs, tourmaline stabilizes.' },
      { crystal: 'Rose Quartz', id: 'rose-quartz', rationale: 'Malachite transforms; rose quartz heals and soothes what\'s been transformed. Using them in sequence — malachite for the heavy lifting, rose quartz for the recovery — is a classic heart-healing protocol.' },
      { crystal: 'Clear Quartz', id: 'clear-quartz', rationale: 'Clear quartz amplifies malachite\'s transformative work. Use with intention and care — this combination accelerates change significantly.' }
    ],
    conflicts: [
      { crystal: 'Moldavite', id: 'moldavite', reason: 'Both are intensely transformative stones. Together they create an overwhelming vortex of change that can destabilize sensitive practitioners. Each should be worked with separately.' }
    ],
    grid_role: 'Transformation catalyst in shadow work and healing grids; use with grounding stones at corners',

    chakra_filter: ['Heart', 'Solar Plexus'],
    element_filter: 'Earth',
