    color: '#2d3748',
    alt_names: ['Volcanic Glass', 'Apache Tears (nodular form)', 'Glass Agate', 'Dragon Glass'],
    mineral_family: 'Volcanic Glass (Mineraloid)',
    chemical_formula: 'SiO₂ with MgO, Fe₃O₄ (approx.)',
    crystal_system: 'Amorphous (not crystalline)',
