    vedic_tradition: 'Not widely referenced in classical texts but in some Tantric traditions obsidian is associated with Kali and used in rituals of dissolution, release, and fierce protection.',
    tcm_use: 'Corresponds to Kidney energy and the Water element. Strengthens Kidney Yang, anchors the spirit (Zhi), and is used for conditions of deficiency, fear, and rootlessness.',
    five_element_theory: 'Water and Earth — the deep stillness of abyssal waters meeting the solid foundation of earth. Consolidates and anchors the downward-moving energy of Water into the stability of Earth.',
    feng_shui_bagua: 'Career & Life Path (Kan), helpful at entrances for protection',
    feng_shui_placement: 'Near front door facing outward as a powerful protection sentinel. Corners of a room to seal against negative intrusions. NOT in the bedroom for most people — its intense energy can cause disturbing dreams and restless sleep.',
    ancient_lore: 'Obsidian has been used by humans for over 700,000 years — the oldest known human tool material. Aztec priests used obsidian blades in ceremonial sacrifice and mirrors for divination. The Aztec deity Tezcatlipoca carried a "smoking mirror" of obsidian through which he could see all secrets of the world. Ancient Greeks and Romans used it for jewelry and scrying. The name comes from Obsius, a Roman who allegedly first brought it to Rome from Ethiopia.',
    indigenous_traditions: 'Among the most universally sacred and practically used stones in indigenous cultures worldwide. Used for blades, arrowheads, and tools for hundreds of thousands of years. In Apache tradition, Apache tears (obsidian nodules) are sacred grief stones tied to the legend of Apache warriors who leapt from a cliff rather than surrender — their tears crystallized into the black stones.',

    meditation_guidance: 'Obsidian is most powerful for shadow work and deep truth-seeing. Gaze into a polished black obsidian sphere or mirror in candlelight — this is the traditional scrying method. For grounding, hold a piece in each hand and focus on your breath descending into the earth. Always perform a cleansing and grounding ritual after working with obsidian — it stirs powerful material.',
    body_placement: 'Feet or between the feet for intense grounding. Root chakra (base of spine) for protection and earth connection. Hold in the non-dominant hand during shadow work to receive its truth-revealing energy. Do not wear on the body for extended periods unless you are actively engaged in transformation work.',
    space_placement: 'Entrances facing outward to deflect incoming negative energy. Corners of a space to seal and protect. Scrying spheres or mirrors in dedicated divination spaces. Not recommended for relaxation spaces or bedrooms for most practitioners.',
    elixir_safety: 'Indirect',
    elixir_notes: 'Obsidian is primarily silicon dioxide but contains various metal oxides (iron, magnesium) that can leach into water. Additionally, natural obsidian can have razor-sharp edges that present a physical hazard. Use the indirect method only and handle carefully.',
    jewelry_recommendations: 'Spectacular in cabochons, spheres, and carved pieces. Rainbow and sheen obsidian are particularly prized. Mohs 5.5 — wear carefully in rings; better suited for pendants and earrings. The conchoidal fracture means edges can be extremely sharp — handle raw pieces with care.',

    safe_cleansing: ['Smoke cleansing', 'Sound bath', 'Moonlight', 'Visualization and breath', 'Brief running water (for polished specimens)'],
    unsafe_cleansing: ['Extended water soaking', 'Salt water over time'],
    charging_methods: ['New moon (dark moon energy matches obsidian\'s frequency)', 'Earth burial overnight', 'Saturn\'s day (Saturday) intention ritual', 'Selenite plate'],
    storage_guidance: 'Handle raw obsidian with extreme care — freshly fractured edges are surgically sharp. Store polished pieces wrapped in soft cloth. Keep away from children. Mohs 5.5 — can be scratched by quartz and harder stones.',
    cautions: 'Raw, freshly knapped obsidian has edges sharper than surgical steel — treat as a bladed tool. The stone\'s energy is intense; new practitioners should work with it gradually and always with grounding support. After intense sessions, cleanse thoroughly.',
    toxicity: 'Non-toxic for normal handling; handle raw specimens carefully due to sharp edges',
    fragility: 'Moderate — Mohs 5.5; conchoidal fracture produces sharp edges; protect polished surfaces',

    synergies: [
      { crystal: 'Black Tourmaline', id: 'black-tourmaline', rationale: 'The two great protection stones — obsidian reveals and reflects while tourmaline absorbs and transmutes. Together they form the most comprehensive energetic protection available in the mineral kingdom.' },
      { crystal: 'Selenite', id: 'selenite', rationale: 'Selenite cleanses and elevates the heavy energy that obsidian draws out. After deep shadow work with obsidian, selenite performs the necessary energetic clearing and repair.' },
      { crystal: 'Amethyst', id: 'amethyst', rationale: 'Amethyst\'s calming wisdom helps integrate what obsidian\'s truth-revealing brings to the surface. Together they support the full arc of shadow work: revelation (obsidian) and integration (amethyst).' }
    ],
    conflicts: [
      { crystal: 'Moldavite', id: 'moldavite', reason: 'Both are intensely transformative. Obsidian digs deep into shadow; moldavite accelerates cosmic change. Together they can create overwhelming psychic turbulence — use each separately.' }
    ],
    grid_role: 'Protective anchor in grids; scrying center in divination layouts',

