    origins: ['Morocco', 'Mexico', 'United States', 'Australia', 'Brazil', 'Naica, Mexico (Cave of Crystals)'],
    rarity: 'Common',
    ethical_sourcing: 'Widely available. Morocco (Khénifra region) is the largest commercial source. The Cave of the Crystals in Naica, Mexico contains the largest known natural crystals (up to 12m), but this is a protected site — commercial stone comes from smaller surface deposits. Look for vendors who source from family-run Moroccan operations.',
    simulant_warnings: 'Satin spar (fibrous selenite) is the most commonly sold form — sometimes incorrectly called "selenite" in commercial markets, though it is technically a variety of the same mineral. True plate selenite is flat and clearer. Ice clear selenite is sometimes confused with glass.',

    short_intention: 'Cleanse the energy field, invite divine light, open the crown to higher guidance',
