    vedic_tradition: 'Associated with Chandra (the Moon) in Jyotish. Selenite amplifies lunar energy and is used in rituals honoring the moon, especially during full and new moon cycles.',
    tcm_use: 'Corresponds to Heart and Lung energy. Nourishes Heart Yin, calms the Shen (spirit-mind), and clears accumulated heat and agitation from the upper warmer.',
    five_element_theory: 'Metal and Water — the clarity and precision of Metal combined with the deep stillness of Water. Supports the Lungs and the capacity to let go — releasing what is held in order to receive what is needed.',
    feng_shui_bagua: 'Center (Health & Unity), Helpful People (Qian)',
    feng_shui_placement: 'Center of a home for clearing and harmonizing all areas. Bedroom for peaceful sleep and calming energy. Meditation room as a permanent altar stone. Doorways and windowsills to keep the home\'s energy clear.',
    ancient_lore: 'Named for Selene, the Greek goddess of the Moon. Ancient Greeks believed selenite was formed from the crystallized light of the moon. Selenite wands have been found in Bronze Age sites across Europe, suggesting it was used ceremonially for thousands of years. The Cave of the Crystals in Naica, Mexico contains selenite crystals up to 11 meters long — formed over 500,000 years in a geothermal brine — described as a real-world Fortress of Solitude.',
    indigenous_traditions: 'Used in various shamanic traditions as a "light stone" for ceremony. Some Pueblo peoples of the American Southwest used thin selenite sheets as window panes in kivas (ceremonial rooms) — it is translucent enough to filter light while maintaining privacy and sacred space.',

    meditation_guidance: 'Hold a selenite wand or plate during meditation to activate the Crown chakra and invite divine light into the upper energy centers. Place selenite above your head while lying in a crystal layout to open a channel to higher guidance. Use before any meditation or healing session to clear the space and your field. After working with heavy or intense stones (obsidian, malachite), rest with selenite to cleanse and restore your aura.',
    body_placement: 'Crown of the head to open the crown chakra. Along the spine to support energetic alignment. Held in both hands at the end of an energy healing session. Above the head in crystal layouts to connect to Source energy.',
    space_placement: 'Anywhere in the home as a continuous environmental cleanser. Charging plate under or near your crystal collection. Bedroom for peaceful sleep. Near doorways to keep the home\'s energy flowing and clear.',
    elixir_safety: 'Avoid',
    elixir_notes: 'SAFETY WARNING: Selenite is hydrated calcium sulfate — it is water-soluble and will physically dissolve if submerged in water. Do not use for any water preparation. Do not cleanse selenite with water for this reason either. This is a fundamental property of the mineral, not a trace concern.',
    jewelry_recommendations: 'Mohs 2 — extremely soft, unsuitable for rings or bracelets subject to friction. Best as pendants in protective settings with no exposed edges. Selenite\'s beauty is best appreciated in wands, plates, towers, and raw specimens rather than jewelry. The silky pearlescence is most visible in larger pieces.',

    safe_cleansing: ['Sound bath', 'Moonlight', 'Smoke (brief — it is fragile so handle gently)', 'Visualization and breath', 'Burying in dry earth or dry salt (NOT wet)'],
    unsafe_cleansing: ['Water in any form — will dissolve the stone', 'Salt water — highly damaging', 'Prolonged physical contact with moist surfaces'],
    charging_methods: ['Full moon overnight (most traditional method — named for Selene)', 'Sunlight for orange selenite varieties', 'Sound frequency 963 Hz', 'Angelic invocation and prayer'],
    storage_guidance: 'Keep absolutely dry — any sustained moisture exposure will etch and eventually dissolve the surface. Store away from humidity, bathrooms, and outdoor moisture. Keep away from hard objects that could scratch the Mohs 2 surface. Selenite is fragile — do not drop. Store in a dry cloth or velvet pouch.',
    cautions: 'Never expose to water — it dissolves. Extremely soft (Mohs 2) and fragile. Handle all pieces, especially towers and wands, with care. Keep dry at all times.',
    toxicity: 'Non-toxic externally; calcium sulfate is inert — just keep dry',
